package com.sunwayworld.framework.converter.bool;
import com.sunwayworld.framework.converter.*;import com.sunwayworld.framework.converter.string.StringToNumberConverterFactory;
public enum BooleanToNumberConverterFactory implements ConverterFactory<Boolean,Number>{INSTANCE;public <T extends Number> Converter<Boolean,T> getConverter(Class<T>targetType){return new BooleanToNumberConverter<T>(targetType);}private class BooleanToNumberConverter<T extends Number> implements Converter<Boolean,T>{private final Class<T>numberType;public BooleanToNumberConverter(Class<T>t){numberType=t;}public Class<Boolean>getSourceType(){return Boolean.class;}public Class<T>getTargetType(){return numberType;}public T convert(Boolean source){if(source==null)return null;return StringToNumberConverterFactory.INSTANCE.getConverter(numberType).convert(Boolean.TRUE.equals(source)?"1":"0");}}}
